
INSERT OR REPLACE INTO content (slug, lang, type, title, description, published_at, repository, updates, series_slug, series_section, project_slug, container_order, updated_at)
VALUES ('implementing-value-objects-in-nodejs', 'en', 'post', 'Implementing Value Objects in Node.js', 'Implementing Value Objects in TypeScript and Node.js by building five real cases, from an email to a price, where every rule of the domain lives in a single place.', '2025-11-02', 'https://github.com/poschuler/nodejs-ddd-value-objects', '[{"date":"2026-09-07","note":"Rewritten end to end. Spanish is now where this post is written first, and this English version was translated from it by an LLM. It adds three value objects — Amount, Currency and Price — plus serialization and why Set and Map do not honor equality by value."}]', NULL, NULL, NULL, NULL, CURRENT_TIMESTAMP);

