INSERT OR REPLACE INTO series (slug, lang, title, description, status, starting_point, destination, out_of_scope, audience, updated_at)
VALUES ('pragmatic-nodejs-api', 'en', 'Pragmatic Node.js API', 'Build a monolithic Node.js API: structure, validation, persistence, tests, access control and a deployment.', 'ongoing', 'You can build a CRUD endpoint with Express and TypeScript, but you do not know how to structure the project as it grows.', 'A monolithic API with real persistence, tests, access control and basic observability, deployed — one you can hold up in production and keep changing without fear.', '["Microservices","Event sourcing","CQRS","Modular monolith"]', 'You want to build a monolithic Node.js API you can deploy to production and keep evolving over time.', CURRENT_TIMESTAMP);

INSERT OR REPLACE INTO series (slug, lang, title, description, status, starting_point, destination, out_of_scope, audience, updated_at)
VALUES ('pragmatic-nodejs-api', 'es', 'Pragmatic Node.js API', 'Construye una API monolítica en Node.js: estructura, validación, persistencia, pruebas, control de acceso y un despliegue.', 'ongoing', 'Sabes construir un endpoint CRUD con Express y TypeScript, pero no sabes cómo estructurar el proyecto a medida que crece.', 'Una API monolítica con persistencia real, pruebas, control de acceso y observabilidad básica, desplegada: una que puedas sostener en producción.', '["Microservices","Event sourcing","CQRS","Modular monolith"]', 'Quieres construir una API monolítica en Node.js que puedas desplegar en producción y evolucionar en el tiempo.', CURRENT_TIMESTAMP);

